function redeem(
        address receiver,
        uint256 amountSharesToRedeem,
        address tokenOut,
        uint256 minTokenOut,
        bool burnFromInternalBalance
    ) external returns (uint256 amountTokenOut) {
        // Calculate the actual exchange rate using market data
        uint256 actualExchangeRate = getMarketPrice(tokenOut);
        uint256 syBalance = getSyBalance(receiver);
        amountTokenOut = (actualExchangeRate * syBalance) / 1e18;
        require(amountTokenOut >= minTokenOut, "Insufficient output amount");
        // Proceed with redeeming shares
        // ... (rest of the redeem logic)
    }

function exchangeRate() external view returns (uint256 res) {
        // Use the market price to determine the exchange rate
        uint256 marketPrice = getMarketPrice();
        uint256 syBalance = getSyBalance(msg.sender);
        res = (marketPrice * syBalance) / 1e18;
    }

